static struct Tab tabs[MAX_TABS]; static int ntabs=1, active=0, safe_mode=1, downloads=0, ads_blocked=1;
static struct Window *w; static char input[256]="about:qrx"; static int inlen=9;
static char bookmarks[BOOKMARKS][256]; static int nbook=0; static ULONG parent_pin_hash=0; static int parent_unlocked=0;
static ULONG pinhash(const char*s){ULONG h=2166136261UL;while(*s){h^=(UBYTE)*s++;h*=16777619UL;}return h;}
static void load_parent(void){BPTR f=Open((STRPTR)"QRX:Prefs/qrxweb-parent.cfg",MODE_OLDFILE);char b[96];if(!f){parent_pin_hash=pinhash("0000");return;}while(FGets(f,(STRPTR)b,sizeof(b))){if(!strncmp(b,"PINHASH=",8))parent_pin_hash=(ULONG)strtoul(b+8,0,16);else if(!strncmp(b,"SAFE=",5))safe_mode=atoi(b+5)?1:0;else if(!strncmp(b,"DOWNLOADS=",10))downloads=atoi(b+10)?1:0;}Close(f);if(!parent_pin_hash)parent_pin_hash=pinhash("0000");}
static void save_parent(void){BPTR f=Open((STRPTR)"QRX:Prefs/qrxweb-parent.cfg",MODE_NEWFILE);char b[128];if(!f)return;snprintf(b,sizeof(b),"PINHASH=%08lx\nSAFE=%d\nDOWNLOADS=%d\n",(unsigned long)parent_pin_hash,safe_mode,downloads);FPuts(f,(CONST_STRPTR)b);Close(f);}
static void load_bookmarks(void){BPTR f=Open((STRPTR)"QRX:Prefs/qrxweb-bookmarks.txt",MODE_OLDFILE);char b[256];if(!f)return;while(nbook<BOOKMARKS&&FGets(f,(STRPTR)b,sizeof(b))){char*p=strchr(b,'\n');if(p)*p=0;if(*b)strncpy(bookmarks[nbook++],b,255);}Close(f);}
#define button(r,x,y,ww,label) qrx_theme_button((r),(x),(y),(ww),(label))
static int ctx=0;
static void draw_context(void){struct RastPort*r=w->RPort;int x=w->MouseX,y=w->MouseY;if(x>w->Width-170)x=w->Width-170;if(y>w->Height-125)y=w->Height-125;qrx_theme_box(r,1,x,y,x+165,y+118);qrx_theme_outline(r,2,x,y,x+165,y+118);qrx_theme_text(r,3,x+8,y+17,"Back");qrx_theme_text(r,3,x+8,y+37,"Forward");qrx_theme_text(r,3,x+8,y+57,"Reload");qrx_theme_text(r,3,x+8,y+77,"Copy URL");qrx_theme_text(r,3,x+8,y+97,"Save page");qrx_theme_text(r,3,x+8,y+115,"Open link/new tab");}
static void add_bookmark(void){BPTR f;if(nbook>=BOOKMARKS)return;strncpy(bookmarks[nbook++],tabs[active].url,255);f=Open((STRPTR)"QRX:Prefs/qrxweb-bookmarks.txt",MODE_NEWFILE);if(f){int i;for(i=0;i<nbook;i++){FPuts(f,(CONST_STRPTR)bookmarks[i]);FPuts(f,(CONST_STRPTR)"\n");}Close(f);}}
static void hist_push(struct Tab*t,const char*u){if(t->hpos>=0&&t->hpos<t->hcount&&!strcmp(t->hist[t->hpos],u))return;if(t->hcount<HIST)t->hcount++;else{int i;for(i=1;i<HIST;i++)strcpy(t->hist[i-1],t->hist[i]);}t->hpos=t->hcount-1;strncpy(t->hist[t->hpos],u,255);}

static int contains_ci(const char *s,const char *n){size_t i,j,l=strlen(n);if(!l)return 1;for(i=0;s[i];i++){for(j=0;j<l&&s[i+j]&&tolower((unsigned char)s[i+j])==tolower((unsigned char)n[j]);j++);if(j==l)return 1;}return 0;}
static int blocked(const char *u){static const char *ads[]={"doubleclick","googlesyndication","adservice","/ads/","tracker","analytics","pixel.","telemetry",0};static const char *adult[]={"porn","xxx","casino","betting","gambling",0};int i;for(i=0;ads[i];i++)if(contains_ci(u,ads[i]))return 1;if(safe_mode)for(i=0;adult[i];i++)if(contains_ci(u,adult[i]))return 1;return 0;}
static void line(struct RastPort*r,int x,int y,const char*s){Move(r,x,y);Text(r,(STRPTR)s,strlen(s));}
static void button_old(struct RastPort*r,int x,int y,int ww,const char*s){SetAPen(r,qrx_theme_legacy_pen(1));RectFill(r,x,y,x+ww,y+16);SetAPen(r,qrx_theme_legacy_pen(3));line(r,x+4,y+12,s);SetAPen(r,qrx_theme_legacy_pen(1));}
static void strip_html(const char *src,char *dst,int cap){int tag=0,space=0,o=0;char tagbuf[80];int ti=0;while(*src&&o<cap-2){char c=*src++;if(c=='<'){tag=1;ti=0;continue;}if(tag){if(c=='>'){tagbuf[ti]=0;tag=0;if(contains_ci(tagbuf,"script")||contains_ci(tagbuf,"video")||contains_ci(tagbuf,"audio")||contains_ci(tagbuf,"iframe")){const char*p=" [BLOCKED MEDIA] ";while(*p&&o<cap-1)dst[o++]=*p++;}else if(contains_ci(tagbuf,"img")){const char*p=" [IMAGE] ";while(*p&&o<cap-1)dst[o++]=*p++;}else if(tagbuf[0]=='p'||tagbuf[0]=='h'||contains_ci(tagbuf,"br")||contains_ci(tagbuf,"li")){dst[o++]='\n';}space=0;}else if(ti<78)tagbuf[ti++]=c;continue;}if(c=='&'){while(*src&&*src!=';'&&src-src<16)src++;if(*src==';')src++;c=' ';}if(isspace((unsigned char)c)){if(!space){dst[o++]=' ';space=1;}}else{dst[o++]=c;space=0;}}dst[o]=0;}
static int fetch(const char *url,char *out,int cap){BPTR f;LONG n;char netstat[160];if(blocked(url)){snprintf(out,cap,"QRX Web Safe Mode blocked this address.\nParental controls prevented the request.");return 0;}if(!strcmp(url,"about:network")){snprintf(out,cap,"QRX Web native network diagnostics\nbsdsocket.library: %s\nDNS/TCP/HTTP: native\nHTTPS/TLS: AmiSSL backend required; never downgraded to plaintext\nExternal wget/curl dependency: removed for page fetch\nTry http://example.com for transport validation.",qrx_net_available()?"AVAILABLE":"NOT AVAILABLE");return 1;}if(!strncmp(url,"about:qrx",9)){snprintf(out,cap,"QRX Web 68K Functional Core\nNative bsdsocket DNS/TCP/HTTP transport. HTTPS is fail-closed until AmiSSL is available.\nLocal test suite is the default page. about:network shows transport status.");return 1;}if(!strcmp(url,"about:benchmark")){static const char sample[]="<html><body><h1>QRX</h1><p>68K parser benchmark <b>bold</b> text</p></body></html>";static char clean[512];clock_t a=clock(),b;int i;for(i=0;i<2000;i++)strip_html(sample,clean,sizeof(clean));b=clock();snprintf(out,cap,"QRX Web parser benchmark\nIterations: 2000\nElapsed ticks: %ld\nCLOCKS_PER_SEC: %ld\nScore ops/sec: %ld",(long)(b-a),(long)CLOCKS_PER_SEC,(long)((b>a)?(2000L*CLOCKS_PER_SEC/(b-a)):0));return 1;}if(!strncmp(url,"file://",7)){const char*path=url+7;f=Open((STRPTR)path,MODE_OLDFILE);if(!f){snprintf(out,cap,"Local file open failed: %s",path);return 0;}n=Read(f,out,cap-1);Close(f);if(n<0)n=0;out[n]=0;{static char clean[PAGE];strip_html(out,clean,sizeof(clean));strncpy(out,clean,cap-1);out[cap-1]=0;}return 1;}if(!strncmp(url,"https://",8)){snprintf(out,cap,"HTTPS requested: %s\n\nQRX Web will not downgrade HTTPS to HTTP. Native TCP is active, but this build needs the AmiSSL TLS backend/SDK to establish TLS and validate certificates. Open about:network for status.",url);return 0;}if(!strncmp(url,"http://",7)){if(!qrx_net_http_get(url,out,cap,netstat,sizeof(netstat))){snprintf(out,cap,"Native network error: %s\nURL: %s",netstat,url);return 0;}{static char clean[PAGE];strip_html(out,clean,sizeof(clean));strncpy(out,clean,cap-1);out[cap-1]=0;}return 1;}snprintf(out,cap,"Unsupported URL scheme: %s",url);return 0;}
static int is_testsuite(void){return contains_ci(tabs[active].url,"QRX-test-suite-page.html");}
static void draw_testsuite(struct RastPort*r){int x=10,y=92,ww=w->Width-20;char b[120];SetAPen(r,qrx_theme_legacy_pen(1));RectFill(r,x,y,x+ww,y+40);SetAPen(r,qrx_theme_legacy_pen(3));line(r,x+10,y+16,"QRX TEST SUITE PAGE");line(r,x+10,y+31,"HTML/CSS / images / forms / table / benchmark");y+=50;SetAPen(r,qrx_theme_legacy_pen(1));RectFill(r,x,y,x+ww/2-5,y+86);RectFill(r,x+ww/2+5,y,x+ww,y+86);SetAPen(r,qrx_theme_legacy_pen(3));line(r,x+8,y+16,"Typography & Layout");line(r,x+8,y+34,"Bold / Italic / Entities / Lists");line(r,x+ww/2+13,y+16,"Image pipeline");SetAPen(r,qrx_theme_legacy_pen(2));RectFill(r,x+ww/2+16,y+26,x+ww/2+176,y+70);SetAPen(r,qrx_theme_legacy_pen(3));line(r,x+ww/2+24,y+52,"QRX IMAGE TEST");y+=96;SetAPen(r,qrx_theme_legacy_pen(1));RectFill(r,x,y,x+ww,y+70);SetAPen(r,qrx_theme_legacy_pen(3));line(r,x+8,y+16,"Form Controls");SetAPen(r,qrx_theme_legacy_pen(0));RectFill(r,x+12,y+25,x+180,y+43);SetAPen(r,qrx_theme_legacy_pen(3));line(r,x+16,y+38,"QRX 68K");button(r,x+195,y+25,70,"CHECK");button(r,x+275,y+25,80,"68020 v");button(r,x+365,y+25,90,"TEST BUTTON");y+=80;SetAPen(r,qrx_theme_legacy_pen(1));RectFill(r,x,y,x+ww,y+48);SetAPen(r,qrx_theme_legacy_pen(3));line(r,x+8,y+16,"Table: Feature        Expected");line(r,x+8,y+32,"Local HTML            PASS    Forms/Image layout PASS");snprintf(b,sizeof(b),"Renderer: QRX Web mini HTML visual test | benchmark: about:benchmark");line(r,x+8,y+45,b);}
static void draw(void){struct RastPort*r=w->RPort;int i,y=96,pos=0,row=0,maxchars=(w->Width-24)/8;char buf[100];qrx_theme_frame(w,"Web");SetAPen(r,qrx_theme_legacy_pen(1));button(r,4,34,28,"<");button(r,35,34,28,">");button(r,66,34,28,"R");button(r,97,34,28,"+");button(r,128,34,38,"SAFE");SetAPen(r,qrx_theme_legacy_pen(1));RectFill(r,170,34,w->Width-45,50);SetAPen(r,qrx_theme_legacy_pen(0));line(r,174,46,input);SetAPen(r,qrx_theme_legacy_pen(1));button(r,w->Width-42,34,36,"GO");for(i=0;i<ntabs;i++){int x=4+i*96;button(r,x,55,92,i==active?"* TAB":"TAB");}SetAPen(r,qrx_theme_legacy_pen(1));line(r,6,86,"HTML/CSS  JS:OFF  ADS:BLOCK  MEDIA:LAZY");if(is_testsuite()){draw_testsuite(r);pos=strlen(tabs[active].text);y=w->Height;}while(tabs[active].text[pos]&&y<w->Height-25){int k=0;if(row++<tabs[active].scroll){while(tabs[active].text[pos]&&tabs[active].text[pos++]!='\n');continue;}while(tabs[active].text[pos]&&tabs[active].text[pos]!='\n'&&k<maxchars-1)buf[k++]=tabs[active].text[pos++];if(tabs[active].text[pos]=='\n')pos++;buf[k]=0;line(r,8,y,buf);y+=10;}snprintf(buf,sizeof(buf),"Tab %d/%d | Safe:%s | Ads:%s | DL:%s | B:%d | Alt+B bookmark Alt+P parent",active+1,ntabs,safe_mode?"ON":"OFF",ads_blocked?"ON":"OFF",downloads?"ON":"OFF",nbook);line(r,8,w->Height-8,buf);}
static void draw_address(void){struct RastPort*r=w->RPort;SetAPen(r,qrx_theme_legacy_pen(1));RectFill(r,170,34,w->Width-45,50);SetAPen(r,qrx_theme_legacy_pen(3));line(r,174,46,input+(inlen>48?inlen-48:0));}
static void go(void){if(input[0]&&!strchr(input,':')){char u[256];snprintf(u,sizeof(u),"https://%s",input);strncpy(input,u,255);input[255]=0;inlen=strlen(input);}strncpy(tabs[active].url,input,255);hist_push(&tabs[active],input);tabs[active].scroll=0;fetch(input,tabs[active].text,PAGE);draw();}
static void navhist(int d){struct Tab*t=&tabs[active];int p=t->hpos+d;if(p<0||p>=t->hcount)return;t->hpos=p;strncpy(input,t->hist[p],255);inlen=strlen(input);strncpy(t->url,input,255);t->scroll=0;fetch(input,t->text,PAGE);draw();}
static void download_current(void){char cmd[700],path[96];if(!downloads||!parent_unlocked){strncpy(tabs[active].text,"Downloads are locked by QRX Web parental controls. Unlock parental mode first.",PAGE-1);draw();return;}snprintf(path,sizeof(path),"RAM:qrxweb-download.bin");snprintf(cmd,sizeof(cmd),"C:wget -q -O %s \"%s\"",path,tabs[active].url);if(SystemTags((STRPTR)cmd,TAG_DONE)!=0){snprintf(tabs[active].text,PAGE,"Download failed: %s",tabs[active].url);draw();return;}snprintf(cmd,sizeof(cmd),"QRX:C/ARESAntivirus %s",path);if(SystemTags((STRPTR)cmd,TAG_DONE)!=0){DeleteFile((STRPTR)path);strncpy(tabs[active].text,"ARES rejected or could not validate the download. Temporary file removed.",PAGE-1);}else strncpy(tabs[active].text,"Download passed ARES scan and is available as RAM:qrxweb-download.bin",PAGE-1);draw();}
int main(void){ULONG sig;int drag=0;WORD dx=0,dy=0;struct Screen*s=0;LONG dragx=0,dragy=0,dragleft=0,dragtop=0;IntuitionBase=(struct IntuitionBase*)OpenLibrary((CONST_STRPTR)"intuition.library",39);GfxBase=(struct GfxBase*)OpenLibrary((CONST_STRPTR)"graphics.library",39);DOSBase=(struct DosLibrary*)OpenLibrary((CONST_STRPTR)"dos.library",39);if(!IntuitionBase||!GfxBase||!DOSBase)return 20;qrx_theme_load();s=LockPubScreen(0);if(!s)return 20;load_parent();load_bookmarks();strcpy(tabs[0].url,"file://QRX:Documents/QRX-test-suite-page.html");strcpy(input,tabs[0].url);inlen=strlen(input);tabs[0].hpos=-1;hist_push(&tabs[0],tabs[0].url);fetch(tabs[0].url,tabs[0].text,PAGE);w=OpenWindowTags(NULL,WA_Title,(IPTR)"QRX Web",WA_Left,18,WA_Top,28,WA_Width,600,WA_Height,410,WA_Flags,WFLG_ACTIVATE|WFLG_BORDERLESS|WFLG_RMBTRAP|WFLG_REPORTMOUSE,WA_IDCMP,IDCMP_MOUSEBUTTONS|IDCMP_MOUSEMOVE|IDCMP_RAWKEY|IDCMP_VANILLAKEY|IDCMP_REFRESHWINDOW|IDCMP_INTUITICKS,TAG_DONE);if(!w)return 20;draw();sig=1UL<<w->UserPort->mp_SigBit;for(;;){struct IntuiMessage*m;Wait(sig);while((m=(struct IntuiMessage*)GetMsg(w->UserPort))){ULONG c=m->Class;UWORD code=m->Code;WORD x=m->MouseX,y=m->MouseY;ReplyMsg((struct Message*)m);if(c==IDCMP_INTUITICKS){if(y>=34&&y<=73)qrx_theme_tooltip(w,x+8,y+12,"Browser control - right click for page menu");}
else if(c==IDCMP_REFRESHWINDOW){BeginRefresh(w);draw();EndRefresh(w,TRUE);}else if(c==IDCMP_MOUSEBUTTONS&&code==SELECTDOWN){if(y<28){if(qrx_theme_close_hit(w,x,y))goto done;if(qrx_theme_back_hit(w,x,y)){WindowToBack(w);}else if(qrx_theme_drag_hit(w,x,y)){drag=1;dx=x;dy=y;dragx=s->MouseX;dragy=s->MouseY;dragleft=w->LeftEdge;dragtop=w->TopEdge;}}else if(y>=34&&y<51&&x>=4&&x<32){navhist(-1);}else if(y>=34&&y<51&&x>=35&&x<63){navhist(1);}else if(y>=34&&y<51&&x>=66&&x<94){go();}else if(y>=34&&y<51&&x>=97&&x<125&&ntabs<MAX_TABS){active=ntabs++;tabs[active].hpos=-1;strcpy(input,"about:qrx");inlen=9;hist_push(&tabs[active],input);fetch(input,tabs[active].text,PAGE);draw();}else if(y>=55&&y<73){int t=(x-4)/96;if(t>=0&&t<ntabs){active=t;strncpy(input,tabs[t].url,255);inlen=strlen(input);draw();}}else if(y>=34&&y<51&&x>=128&&x<166){if(parent_unlocked){safe_mode=!safe_mode;save_parent();}else{strncpy(tabs[active].text,"Parental lock active. Press Alt+P and enter the parent PIN in the address field as pin:NNNN. Default first-run PIN is 0000.",PAGE-1);}draw();}else if(y>=34&&y<51&&x>w->Width-45)go();}else if(c==IDCMP_MOUSEBUTTONS&&code==MENUDOWN){ctx=1;draw_context();}
else if(c==IDCMP_MOUSEBUTTONS&&code==MENUUP){ctx=0;draw();}
else if(c==IDCMP_MOUSEBUTTONS&&code==SELECTUP){drag=0;}else if(c==IDCMP_MOUSEMOVE&&drag){LONG nl=dragleft+(LONG)s->MouseX-dragx,nt=dragtop+(LONG)s->MouseY-dragy;MoveWindow(w,nl-w->LeftEdge,nt-w->TopEdge);}else if(c==IDCMP_VANILLAKEY){if(code==13||code==10)go();else if(code==8||code==127){if(inlen)input[--inlen]=0;draw_address();}else if(code>=32&&code<=126&&inlen<250){input[inlen++]=(char)code;input[inlen]=0;draw_address();}}else if(c==IDCMP_RAWKEY){if(code==0x44){if(!strncmp(input,"pin:",4)){if(pinhash(input+4)==parent_pin_hash){parent_unlocked=1;downloads=1;save_parent();strcpy(tabs[active].text,"Parent controls unlocked for this QRX Web session. SAFE may now be toggled; downloads enabled and ARES-gated.");}else strcpy(tabs[active].text,"Incorrect parent PIN.");draw();}else if(!strcmp(input,"bookmark:")){add_bookmark();draw();}else if(!strcmp(input,"download:")){download_current();}else go();}else if(code==0x41&&inlen){input[--inlen]=0;draw();}else if(code==0x4c){if(tabs[active].scroll>0)tabs[active].scroll--;draw();}else if(code==0x4d){tabs[active].scroll++;draw();}}}}done:CloseWindow(w);if(s)UnlockPubScreen(0,s);if(DOSBase)CloseLibrary((struct Library*)DOSBase);if(GfxBase)CloseLibrary((struct Library*)GfxBase);if(IntuitionBase)CloseLibrary((struct Library*)IntuitionBase);return 0;}
